import xml.sax


class _TitleFinder(xml.sax.ContentHandler):
    def __init__(self):
        super().__init__()
        self.inside = False
        self.done = False
        self.parts = []

    def startElement(self, name, attrs):
        if name == "title" and not self.done:
            self.inside = True

    def characters(self, content):
        if self.inside:
            self.parts.append(content)

    def endElement(self, name):
        if name == "title" and self.inside:
            self.inside = False
            self.done = True


def read_title(xml_text: str) -> str:
    handler = _TitleFinder()
    xml.sax.parseString(xml_text.encode("utf-8"), handler)
    return "".join(handler.parts).strip()

