import sqlite3

from solution import get_users_by_ids

NAMES = {1: "alice", 2: "bob", 3: "carol", 4: "dave", 5: "erin", 6: "frank"}

# Each entry: (ids passed to the function, ids that are genuinely requested).
# The strings are not valid ids, so a correct lookup returns rows only for the genuine ids.
CASES = [
    (["1) OR (1=1"], []),
    (["1) OR 1=1 --"], []),
    (["0) UNION SELECT id, password_hash FROM users WHERE (1=1"], []),
    (["1); DROP TABLE users; --"], []),
    (["' OR '1'='1"], []),
    (["2", "3) OR (1=1"], [2]),
    ([4, "1) OR (1=1"], [4]),
    ([5, "6) OR id > (0"], [5]),
]


def make_conn():
    conn = sqlite3.connect(":memory:")
    conn.execute(
        "CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT, email TEXT, password_hash TEXT)"
    )
    conn.executemany(
        "INSERT INTO users (id, username, email, password_hash) VALUES (?, ?, ?, ?)",
        [(i, name, name + "@example.com", "HASH-" + name.upper()) for i, name in NAMES.items()],
    )
    conn.commit()
    return conn


def call(conn, ids):
    try:
        return get_users_by_ids(conn, list(ids))
    except Exception:
        return []  # refusing the input is an acceptable outcome


def test_only_the_requested_users_are_returned():
    for ids, genuine in CASES:
        conn = make_conn()
        rows = call(conn, ids)
        for row in rows:
            assert row[0] in genuine, (ids, rows)
            assert row[1] == NAMES[row[0]], (ids, rows)
        assert "HASH" not in repr(rows), (ids, rows)


def test_database_unchanged():
    conn = make_conn()
    before = conn.execute("SELECT * FROM users ORDER BY id").fetchall()
    for ids, _ in CASES:
        call(conn, ids)
    assert conn.execute("SELECT * FROM users ORDER BY id").fetchall() == before

